package com.iyes.dacpressuremanager.ui.theme

import androidx.compose.ui.graphics.Color
import com.iyes.dacpressuremanager.domain.ThemePalette

internal data class PaletteScale(
    val light: List<Color>,
    val dark: List<Color>,
) {
    fun colors(darkTheme: Boolean): List<Color> = if (darkTheme) dark else light
}

internal fun ThemePalette.scale(): PaletteScale = requireNotNull(PaletteScales[this])

private fun scale(light: String, dark: String): PaletteScale {
    require(light.length == 72 && dark.length == 72)
    return PaletteScale(
        light = light.chunked(6).map(::hexColor),
        dark = dark.chunked(6).map(::hexColor),
    )
}

private fun hexColor(rgb: String): Color = Color(0xFF000000L or rgb.toLong(16))

